(() => {
"use strict";
const U=window.DW_UI,V=window.DW_VIEWS,{esc,icon,btn,iconBtn,pill,field,check,notice,table,section,search,shell,targetScene}=U;
V.trajectory=s=>{
 const repair=s.variant==='repair';
 const trajectory=window.DW_RECORDING.currentTrajectory(),source=trajectory.source||window.DW_CATALOG.recordingFixtures.source;
 const scopeName=source.scope==='allDisplays'?'全部 '+source.displayIds.length+' 个显示屏':source.scope==='display'?'单个显示屏':'指定窗口';
 const durationUs=repair?1600000:trajectory.events.at(-1).atUs,selected=trajectory.events.find(e=>e.atUs>0&&['pointer.move','pointer.delta'].includes(e.kind))||trajectory.events[0],selectedAtUs=repair?820000:selected.atUs;
 const repairRows=[['00:00.000','移动指针','相对移动','Δx +18　Δy −6'],['00:00.220','鼠标按下','左键','按下'],['00:00.280','鼠标释放','左键','释放'],['00:00.740','按键按下','Ctrl 左','按下'],['00:00.760','按键按下','S','按下'],['00:00.790','按键释放','S','释放'],['00:00.820','按键释放','Ctrl 左',repair?'缺失释放':'释放']];
 const rows=repair?repairRows:trajectory.events.map(e=>{const kind=e.kind,screen=kind==='pointer.move'?source.topology.displays.find(d=>e.x>=d.bounds.x&&e.x<d.bounds.x+d.bounds.width&&e.y>=d.bounds.y&&e.y<d.bounds.y+d.bounds.height):null;const title=kind==='pointer.move'?'移动指针':kind==='pointer.delta'?'相对移动':kind==='pointer.button'?(e.state==='down'?'鼠标按下':'鼠标释放'):kind==='key.down'?'按键按下':kind==='key.up'?'按键释放':'输入文本';return [(e.atUs/1000000).toFixed(3)+' s',title,screen?.name||({ctrl_l:'Ctrl 左',s:'S'}[e.key])||(e.button==='left'?'左键':'输入'),kind==='pointer.move'?'x '+e.x+' · y '+e.y:kind==='pointer.delta'?'Δx '+e.dx+' · Δy '+e.dy:kind==='pointer.button'?e.state==='down'?'按下':'释放':kind==='key.down'?'按下':kind==='key.up'?'释放':e.text];});
 const ratio=atUs=>Math.max(0,Math.min(100,100*atUs/Math.max(1,durationUs)));
 const bars=kind=>{const held=new Map(),items=[];for(const e of trajectory.events){const key=kind==='keyboard'?e.key:e.button,down=kind==='keyboard'?e.kind==='key.down':e.kind==='pointer.button'&&e.state==='down',up=kind==='keyboard'?e.kind==='key.up':e.kind==='pointer.button'&&e.state==='up';if(down)held.set(key,e);if(up&&held.has(key)){items.push({key,from:held.get(key).atUs,until:e.atUs});held.delete(key);}}for(const [key,e]of held)items.push({key,from:e.atUs,until:durationUs});return items.map((e,i)=>{const left=Math.min(99.7,ratio(e.from)),width=Math.min(100-left,Math.max(.3,ratio(e.until)-left)),label={left:'左键',right:'右键',middle:'中键',ctrl_l:'Ctrl 左',s:'S'}[e.key]||e.key;return '<i class="timeline-bar '+(kind==='button'?'green':'')+'" style="left:'+left+'%;width:'+width+'%;top:'+(kind==='keyboard'&&i%2?30:8)+'px;overflow:hidden" title="'+esc(label)+'">'+esc(label)+'</i>';}).join('');};
 const motion=trajectory.events.filter(e=>['pointer.move','pointer.delta'].includes(e.kind));let motionY=source.initialPointer?.y||0;const plot=motion.map(e=>({atUs:e.atUs,y:e.kind==='pointer.move'?(motionY=e.y):(motionY+=e.dy)})),minY=Math.min(0,...plot.map(e=>e.y)),maxY=Math.max(1,...plot.map(e=>e.y)),motionPath=plot.map((p,i)=>(i?'L':'M')+(7*ratio(p.atUs)).toFixed(2)+' '+(46-38*(p.y-minY)/(maxY-minY)).toFixed(2)).join(' ');
 const body='<main class="page timeline-page">'+section(repair?'修复录制分段':source.scope==='allDisplays'?'跨屏桌面操作':'桌面操作轨迹','录制 / 时间轴编辑',btn('取消','editor-graph')+btn(repair?'应用配对调整':'保存轨迹',repair?'trajectory-editor':'editor-graph','primary','save'))+
 (repair?notice('录制中断，Ctrl 左缺少释放事件','在分段结束处补充释放事件，或移除未配对区间。','amber'):"")+
 '<div class="rec-origin">'+pill(scopeName,'blue')+'<span>桌面物理像素 · 来源布局</span>'+btn('显示屏映射','trajectory-displays','small')+'</div><div class="timeline-work"><div class="stack"><div class="panel"><div class="panel-head"><div class="row">'+icon('mouse',17)+'输入轨迹 '+pill(repair?'分段草稿':'已配对',repair?'amber':'green')+'</div><div class="row">'+btn('播放预览','','small','play')+btn('裁剪','','small','crop')+btn('100%','','small')+'</div></div><div class="timeline"><div class="timeline-scale">'+Array.from({length:5},(_,i)=>(durationUs*i/4/1000000).toFixed(i===4?3:1)+' s').map(x=>'<span>'+x+'</span>').join("")+'</div><div class="track"><span>指针运动</span><div class="track-lane"><svg viewBox="0 0 700 54" preserveAspectRatio="none"><path d="'+(repair?'M0 38Q40 13 95 31T200 19T310 35T450 15T690 30':motionPath)+'" stroke="#7a9fdc" stroke-width="2" fill="none"/></svg></div></div><div class="track"><span>鼠标按钮</span><div class="track-lane">'+(repair?'<i class="timeline-bar green" style="left:14%;width:6%">左键</i>':bars('button'))+'</div></div><div class="track"><span>键盘</span><div class="track-lane">'+(repair?'<i class="timeline-bar amber" style="left:47%;width:42%">Ctrl</i><i class="timeline-bar green" style="left:51%;width:9%;top:30px">S</i>':bars('keyboard'))+'</div></div><div class="playhead" style="left:'+Math.min(96,12+84*selectedAtUs/Math.max(1,durationUs))+'%"><span>'+(selectedAtUs/1000000).toFixed(3)+' s</span></div></div><div class="timeline-transport">'+iconBtn('back','到开头')+iconBtn('play','预览轨迹')+iconBtn('pause','暂停预览')+'<strong>'+(selectedAtUs/1000000).toFixed(3)+' s</strong><span class="muted">/ '+(durationUs/1000000).toFixed(3)+' s</span><span class="spacer"></span><span>完整事件　'+(repair?32:trajectory.events.length)+' 个</span></div></div><div class="panel"><div class="panel-head">事件列表 <span class="muted" style="font-weight:400">按相对时间排序</span></div>'+table(['时间','动作','输入','数值或状态'],rows.map((r,i)=>r.map((v,j)=>j===0?'<span class="mono muted">'+v+'</span>':i===6&&repair&&j===3?pill(v,'amber'):v)))+'</div></div><aside class="panel"><div class="panel-head">'+(repair?'配对修复':'事件属性')+'</div><div class="panel-body stack">'+(repair?notice('需要处理 1 项','在片段结束处补充 Ctrl 左释放，或删除对应按下区间。','amber'):"")+field('事件类型',repair?'释放按键':selected.kind==='pointer.delta'?'相对移动':'移动指针','',{select:['移动指针','相对移动','按下按键','释放按键']})+field('发生时间（毫秒）',repair?'1600':String(selected.atUs/1000))+(repair?field('按键','Ctrl 左'):'<div class="form-grid">'+field(selected.kind==='pointer.delta'?'水平增量':'水平位置',String(selected.x??selected.dx??0))+field(selected.kind==='pointer.delta'?'垂直增量':'垂直位置',String(selected.y??selected.dy??0))+'</div>')+'<div class="divider"></div><div class="info-grid"><div class="info-item">坐标模式<strong>'+({event:'按事件记录',physical:'物理像素',relative:'原始相对移动'}[trajectory.coordinateMode])+'</strong></div><div class="info-item">暂停时长<strong>已扣除</strong></div></div>'+(repair?notice('修复后保存为新版本','可撤销配对调整。'):notice('输入时间轴','鼠标按下与释放使用同一事件序列。'))+'</div></aside></div></main>';
 return shell(s,body,{editor:false});
};
V.capture=s=>{const back=s.parent||'editor-graph';const done=['templates-source','observations-config','observation','match-config'].includes(back)?back:'template-editor';return '<div class="desktop-surface capture-surface">'+targetScene("full")+'<div class="capture-mask"></div><div class="capture-box"><i></i><i></i><i></i><i></i><span class="capture-measure">142 × 56 px</span></div><div class="capture-float"><span>'+icon('crop',18)+'选择模板区域</span><span class="muted">拖动调整 · Esc 取消</span><span class="spacer"></span>'+btn('取消',back)+btn('完成选区',done,'primary','check')+'</div><div class="capture-cross-h"></div><div class="capture-cross-v"></div></div>';};
V.template=s=>shell(s,'<main class="page">'+section('制作图像模板','来源：报表中心 / 本次采集',btn('重新采集','capture-overlay','','crop')+btn('保存模板','asset-image','primary','save'))+'<div class="template-work"><div class="panel"><div class="panel-head">区域预览 <span class="muted" style="font-weight:400">物理像素</span></div><div class="template-stage checkerboard"><div class="template-crop"><span class="sample-download" style="transform:scale(2)">下载所选</span><i></i><i></i><i></i><i></i></div></div><div class="panel-head"><span class="muted">126 × 40 px</span><div class="row">'+btn('−','','small')+btn('200%','','small')+btn('+','','small')+'</div></div></div><aside class="panel"><div class="panel-head">模板属性</div><div class="panel-body stack">'+field('模板名称','下载按钮')+field('所属分类','常用模板','',{select:['常用模板','其他模板']})+'<div class="form-grid">'+field('宽度（px）','126')+field('高度（px）','40')+'</div>'+check('保留透明通道',true)+'<div class="divider"></div><div class="section-label">采集来源</div><div class="info-item">窗口<strong>报表中心</strong></div><div class="info-item">采集时间<strong>今天 09:35</strong></div>'+btn('测试匹配','match-test','','target')+'</div></aside></div></main>',{active:'assets'});
V.match=s=>{
 const multi=s.variant==='ambiguous',none=s.variant==='none';
 let scene=targetScene("preview");
 if(multi){let n=0;scene=scene.replace(/<span class="target-ready">可下载<\/span>/g,()=>++n<4?'<span class="target-ready"><b class="sample-download small-target">下载所选</b></span>':'<span class="target-ready">生成中</span>')}
 return shell(s,'<main class="page">'+section('测试模板定位','模板：下载按钮 v3 · 主目标：报表中心',btn('重新采集','capture-overlay','','crop')+btn('范围与尺度','match-config')+btn('重新测试','match-test','primary','target'))+
 '<div class="match-work"><div class="stack"><div class="panel"><div class="panel-head">当前采集帧 <span class="muted" style="font-weight:400">保持原目标范围</span></div><div class="match-preview '+(multi?'multiple':none?'no-match':'matched')+'">'+scene+'<div class="match-box"><span>'+(multi?'候选 1':'0.97')+'</span></div>'+(multi?'<div class="match-box extra"><span>候选 2</span></div><div class="match-box third"><span>候选 3</span></div>':"")+'</div></div><div class="panel"><div class="panel-head">匹配条件</div><div class="panel-body form-grid">'+field('匹配阈值','0.92')+field('候选选择',multi?'仅唯一候选':'仅唯一候选','',{select:['仅唯一候选','最高分候选']})+field('搜索范围','当前窗口')+field('最大等待（毫秒）','5000')+'</div></div></div><aside class="panel"><div class="panel-head">定位结果 '+pill(none?'未找到':multi?'3 个候选':'唯一候选',none||multi?'amber':'green')+'</div><div class="panel-body stack">'+(none?notice('等待结束，未发现匹配','检查目标区域、图像缩放或重新采集模板。','amber'):multi?notice('需要唯一候选','多个位置达到阈值，本次不生成可直接使用的位置。','amber'):notice('找到唯一位置','点击前会重新核对目标与定位有效性。','green'))+(none?'<div class="empty" style="height:160px">'+icon('target',38)+'<p>没有可用候选</p></div>':table(['候选','分数','尺度'],multi?[['候选 1','0.97','100%'],['候选 2','0.96','100%'],['候选 3','0.94','100%']]:[['候选 1','0.97','100%']]))+'<div class="result-row"><span>图像计算耗时</span><strong>24 ms</strong></div><div class="result-row"><span>模板版本</span><strong>v3</strong></div>'+btn(none?'重新采集':multi?'调整模板':'使用此定位',none?'capture-overlay':multi?'template-editor':'node-properties','primary')+'</div></aside></div></main>');
};
V.observe=s=>window.DW.singleObservation(s);
})();
